<?php
require '../config/app.php'; require_role(['admin','staff']); $title='Review Moderation'; $basePath='../';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$status=$_POST['status'];if(!in_array($status,['Pending','Approved','Rejected'],true))$status='Pending';$st=$pdo->prepare("UPDATE reviews SET status=? WHERE id=?");$st->execute([$status,$id]);flash('success','Review status updated.');redirect('reviews.php');}
$rows=$pdo->query("SELECT r.*,u.name,u.email FROM reviews r JOIN users u ON u.id=r.patient_id ORDER BY r.created_at DESC")->fetchAll();
require '../partials/header.php'; ?>
<div class="card p-3"><div class="d-flex justify-content-between align-items-center mb-3"><div><span class="text-primary fw-semibold">PATIENT REVIEWS</span><h3 class="mt-1">Review moderation</h3></div></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Patient</th><th>Rating</th><th>Review</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong><br><small class="text-muted"><?=e($r['email'])?></small></td><td class="text-warning"><?=str_repeat('★',(int)$r['rating'])?></td><td><?=e($r['review_text'])?></td><td><span class="badge bg-light text-primary"><?=e($r['status'])?></span></td><td><form method="post" class="d-flex gap-1"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><select class="form-select form-select-sm" name="status"><?php foreach(['Pending','Approved','Rejected'] as $s):?><option <?=$r['status']===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach; if(!$rows):?><tr><td colspan="5" class="text-muted">No reviews submitted yet.</td></tr><?php endif;?></tbody></table></div></div>
<?php require '../partials/footer.php'; ?>
